MAX_HISTORY_DAYS = 3

def cleanup_history():
    cutoff = time.time() - MAX_HISTORY_DAYS * 86400
    kept = []
    for item in st.session_state.history:
        if item.get("created", 0) >= cutoff:
            kept.append(item)
        else:
            path = item.get("path")
            if path and os.path.isfile(path):
                try: os.remove(path)
                except OSError: pass
    st.session_state.history = kept

cleanup_history()

def extract_product_page(url):
    """Lấy metadata công khai; một số link TikTok cần đăng nhập nên có thể không đọc được."""
    info = {"title": "", "image": "", "description": ""}
    if not re.match(r"^https?://", url.strip(), re.I):
        raise ValueError("Link phải bắt đầu bằng http:// hoặc https://")
    headers = {"User-Agent": "Mozilla/5.0"}
    try:
        response = requests.get(url.strip(), headers=headers, timeout=18, allow_redirects=True)
        response.raise_for_status()
        html = response.text[:2500000]
        def meta(prop):
            patterns = [
                rf"""<meta[^>]+(?:property|name)=["']{re.escape(prop)}["'][^>]+content=["']([^"']+)""",
                rf"""<meta[^>]+content=["']([^"']+)["'][^>]+(?:property|name)=["']{re.escape(prop)}""",
            ]
            for pattern in patterns:
                match = re.search(pattern, html, re.I)
                if match:
                    return requests.utils.unquote(match.group(1).replace("&amp;", "&"))
            return ""
        info["title"] = meta("og:title") or meta("twitter:title")
        info["image"] = meta("og:image") or meta("twitter:image")
        info["description"] = meta("og:description") or meta("description")
        if not info["title"]:
            match = re.search(r"<title[^>]*>(.*?)</title>", html, re.I | re.S)
            if match:
                info["title"] = re.sub(r"\\s+", " ", match.group(1)).strip()
    except Exception as exc:
        info["error"] = str(exc)
    return info

def get_ffmpeg():
    import imageio_ffmpeg
    return imageio_ffmpeg.get_ffmpeg_exe()

def tts_file(text, voice, path, rate="+0%", pitch="+0Hz"):
    async def _run():
        import edge_tts
        await edge_tts.Communicate(text=text, voice=voice, rate=rate, pitch=pitch).save(path)
    asyncio.run(_run())

def make_script(gemini_key, product, details, style, seconds, character):
    if not gemini_key:
        raise RuntimeError("Cần Gemini API Key để viết kịch bản đúng thông tin sản phẩm. Nhập API key ở phần cấu hình.")
    from google import genai
    from google.genai import types
    prompt = f"""
Bạn là biên kịch video TikTok Shop tiếng Việt tự nhiên, nói như người thật.
Sản phẩm: {product}
Thông tin được xác minh từ trang/khách cung cấp: {details}
Kiểu video: {style}
Nhân vật: {character}
Thời lượng mục tiêu: {seconds} giây.
Viết lời thoại miền Nam Việt Nam gần gũi, rõ chữ, câu nói liền mạch, không dùng giọng miền Bắc,
không bịa giá, chất liệu, kích thước, công dụng, chứng nhận hoặc trải nghiệm chưa có dữ liệu.
Nếu thiếu thông tin thì nói trung tính hoặc bỏ qua. Kịch bản có mở đầu thu hút, cầm/giới thiệu sản phẩm,
nêu 2-3 điểm có căn cứ, kết thúc tự nhiên. Không đọc tên link hay mã sản phẩm.
Trả về JSON object: {{"script":"toàn bộ lời thoại liên tục","visual_prompt":"mô tả hành động nhân vật theo từng nhịp, khớp sản phẩm và lời thoại","caption":"caption ngắn"}}.
"""
    client = genai.Client(api_key=gemini_key)
    res = client.models.generate_content(
        model="gemini-2.5-flash",
        contents=prompt,
        config=types.GenerateContentConfig(response_mime_type="application/json", temperature=0.75),
    )
    raw = re.sub(r"^```(?:json)?\s*|\s*```$", "", (res.text or "").strip(), flags=re.I)
    data = json.loads(raw)
    if not data.get("script") or not data.get("visual_prompt"):
        raise RuntimeError("AI chưa trả về đủ lời thoại và mô tả chuyển động.")
    return data

def choose_character(gender, age, same_character, product_key):
    if same_character and product_key in st.session_state.product_characters:
        return st.session_state.product_characters[product_key]
    gender_text = gender
    age_text = age
    faces = ["gương mặt hiền hậu, nụ cười nhẹ", "gương mặt sáng, biểu cảm tự nhiên", "nét mặt thân thiện, đời thường"]
    desc = f"Người Việt Nam {gender_text}, {age_text}, {random.choice(faces)}, ngoại hình chân thực, da có texture tự nhiên, không làm đẹp quá mức"
    if same_character:
        st.session_state.product_characters[product_key] = desc
    return desc

def upload_fal_image(image_bytes, suffix=".jpg"):
    tmp = tempfile.NamedTemporaryFile(delete=False, suffix=suffix)
    try:
        tmp.write(image_bytes); tmp.close()
        return fal_client.upload_file(tmp.name)
    finally:
        try: os.unlink(tmp.name)
        except OSError: pass

def create_real_motion_video(product_image_bytes, product_title, script_data, character, gender, age, seconds, fal_key):
    os.environ["FAL_KEY"] = fal_key
    product_url = upload_fal_image(product_image_bytes)
    visual_prompt = script_data["visual_prompt"]
    human_prompt = (
        f"Create a photorealistic vertical 9:16 commercial review portrait image. "
        f"{character}. The person is naturally holding and demonstrating the exact product shown in the reference image. "
        f"Preserve product packaging, shape, colors, logo placement and proportions as closely as possible. "
        f"Real Vietnamese home/shop environment, soft natural lighting, realistic skin texture, candid camera framing, "
        f"no extra fingers, no text overlays, no watermark. Product: {product_title}. "
        f"Make the person look like a real customer reviewer, not a synthetic fashion model."
    )
    still = fal_client.subscribe(
        "fal-ai/flux-pro/kontext",
        arguments={"image_url": product_url, "prompt": human_prompt, "aspect_ratio": "9:16"},
        with_logs=False,
    )
    still_url = (still.get("images") or [{}])[0].get("url")
    if not still_url:
        raise RuntimeError("AI tạo nhân vật chưa trả về ảnh tham chiếu.")
    motion_prompt = (
        f"Photorealistic video, vertical 9:16. {character}. "
        f"The reviewer speaks naturally to camera, maintains eye contact, blinks, smiles subtly, "
        f"moves head and shoulders naturally, uses realistic hand gestures and demonstrates the product clearly. "
        f"Keep the exact product consistent with the reference image throughout the clip; do not morph, replace, "
        f"redesign or change its colors or packaging. Natural continuous movement, realistic human timing, "
        f"no frozen pose, no slideshow, no cuts to unrelated products. Action direction: {visual_prompt}"
    )
    clip = fal_client.subscribe(
        "fal-ai/kling-video/v3/standard/image-to-video",
        arguments={
            "image_url": still_url,
            "prompt": motion_prompt,
            "duration": str(seconds),
            "aspect_ratio": "9:16",
            "generate_audio": False,
        },
        with_logs=False,
    )
    video_url = (clip.get("video") or {}).get("url")
    if not video_url:
        raise RuntimeError("Dịch vụ video AI không trả về video.")
    video_response = requests.get(video_url, timeout=120)
    video_response.raise_for_status()
    return video_response.content

def attach_vietnamese_voice(video_bytes, narration, voice, rate, pitch):
    with tempfile.TemporaryDirectory() as folder:
        raw_video = os.path.join(folder, "silent.mp4")
        audio = os.path.join(folder, "voice.mp3")
        final = os.path.join(folder, "final.mp4")
        Path(raw_video).write_bytes(video_bytes)
        tts_file(narration, voice, audio, rate, pitch)
        ffmpeg = get_ffmpeg()
        proc = subprocess.run(
            [ffmpeg, "-y", "-i", raw_video, "-i", audio, "-map", "0:v:0", "-map", "1:a:0",
             "-c:v", "copy", "-c:a", "aac", "-b:a", "192k", "-shortest", "-movflags", "+faststart", final],
            capture_output=True, text=True, timeout=240
        )
        if proc.returncode != 0:
            raise RuntimeError("Không ghép được giọng đọc: " + proc.stderr[-900:])
        return Path(final).read_bytes()

def worker(job_id, link, details, uploaded_bytes, uploaded_name, gender, age, same_character, character_desc,
           style, seconds, gemini_key, fal_key, voice, rate, pitch):
    try:
        product = extract_product_page(link)
        title = product.get("title") or "Sản phẩm TikTok Shop"
        description = product.get("description") or ""
        if uploaded_bytes:
            image_bytes = uploaded_bytes
        elif product.get("image"):
            im = requests.get(product["image"], timeout=30)
            im.raise_for_status()
            image_bytes = im.content
        else:
            raise RuntimeError("Không lấy được ảnh sản phẩm từ link. Hãy tải ảnh sản phẩm lên để AI giữ đúng mẫu.")
        combined_details = "\n".join(x for x in [description, details] if x)
        # Character identity is selected before worker launch and passed as a stable description.
        script = make_script(gemini_key, title, combined_details, style, seconds, character_desc)
        video = create_real_motion_video(image_bytes, title, script, character_desc, gender, age, seconds, fal_key)
        final_video = attach_vietnamese_voice(video, script["script"], voice, rate, pitch)
        outdir = os.path.join(tempfile.gettempdir(), "bap_ai_private_history")
        os.makedirs(outdir, exist_ok=True)
        output_path = os.path.join(outdir, f"{job_id}.mp4")
        Path(output_path).write_bytes(final_video)
        return {"ok": True, "path": output_path, "title": title, "script": script, "created": time.time(), "link": link}
    except Exception as exc:
        return {"ok": False, "error": str(exc), "created": time.time(), "link": link}

